  function commandTime(){return new Date().toISOString().slice(0,19).replace('T',' ')}
  function recordCommand(pile,action,request,status,note){var now=commandTime(),commandMap={'固件升级':'UpdateFirmware','重启设备':'Reset','设备对时':'SetClock','重新生成二维码':'ReplaceQRCode'};maintenanceRecords.unshift({pileId:pile.id,action:action,time:now,status:status,note:note||'操作请求已发送'});deviceLogs.unshift({id:'LOG'+String(202608210001+deviceLogs.length),pileId:pile.id,command:action,requestData:request,message:'[2,"'+pile.id+'","'+(commandMap[action]||action)+'",'+request+']',time:now,status:status==='执行失败'?'发送失败':'发送成功'})}
  function runRemoteCommand(id,action){var pile=findPile(id);if(!pile)return;if(['离线','未激活'].indexOf(pile.status)!==-1){toast('设备不在线，暂不可执行'+action);return}if(pile.activeOrders||pileGuns(pile.id).some(function(gun){return gun.activeOrders||gun.status==='充电中'})){toast('设备正在充电，请结束全部充电订单后再执行'+action);return}var label=action==='upgrade'?'固件升级':action==='restart'?'重启设备':'设备对时';if(action==='upgrade'){showModal('固件升级','<div>设备：'+escapeHtml(pile.name)+'</div><div>当前版本：'+escapeHtml(pile.version)+'</div><div class="form-item" style="margin-top:12px"><label class="filter-label">目标固件版本</label><select class="select-input" id="targetFirmware"><option>V3.2.0</option><option>V3.1.8</option></select></div><div class="warning-card">升级期间设备将暂停服务，请保持设备联网，且不要断电或插入车辆。</div>',[{label:'取消'},{label:'开始升级',primary:true,run:function(){var version=el('targetFirmware')?el('targetFirmware').value:'V3.2.0';pile.version=version;recordCommand(pile,label,'{"version":"'+version+'"}','执行成功','固件已升级至 '+version);toast('固件升级完成，当前版本 '+version);if(state.deviceDetail)showDeviceDetail('pile',id,'日志记录');else renderDeviceModule('pile')}}]);return}simpleModal(label,'确认对充电桩「'+escapeHtml(pile.name)+'」执行'+label+'？设备在线且当前无充电订单。',function(){recordCommand(pile,label,action==='restart'?'{"type":"soft"}':'{"time":"'+commandTime()+'"}','执行成功',label+'已完成');toast(label+'已完成');if(state.deviceDetail)showDeviceDetail('pile',id,'日志记录');else renderDeviceModule('pile')})}
  function removePile(id){var pile=findPile(id);if(!pile)return;var guns=pileGuns(id);if(pile.activeOrders||pile.unsettledOrders||guns.some(function(gun){return gun.activeOrders||gun.unsettledOrders})){toast('无法删除：充电桩或充电枪存在进行中订单或未结算记录');return}simpleModal('删除充电桩','确认删除「'+escapeHtml(pile.name)+'」及其 '+guns.length+' 把充电枪？历史订单、故障与日志记录将保留。',function(){var station=stationForPile(pile);chargingPiles=chargingPiles.filter(function(item){return item.id!==id});chargingGuns=chargingGuns.filter(function(gun){return gun.pileId!==id});if(station)recomputeStation(station);refreshStations();state.deviceSelected={};renderDeviceModule('pile');toast('充电桩及关联充电枪已删除')})}
  function removeGun(id){var gun=findGun(id);if(!gun)return;if(gun.activeOrders||gun.unsettledOrders){toast('无法删除：充电枪存在进行中订单或未结算记录');return}simpleModal('删除充电枪','确认删除充电枪「'+escapeHtml(id)+'」？历史订单和故障记录将保留。',function(){var pile=findPile(gun.pileId),station=stationForPile(pile);chargingGuns=chargingGuns.filter(function(item){return item.id!==id});if(station)recomputeStation(station);refreshStations();state.deviceSelected={};renderDeviceModule('gun');toast('充电枪已删除，所属充电桩枪数量已同步更新')})}
  function runDeviceAction(kind,id,action){document.querySelectorAll('.action-menu-wrap').forEach(function(item){item.classList.remove('open')});if(action==='detail'){showDeviceDetail(kind,id);return}if(action==='edit'){if(kind==='pile')openPileDrawer(id);else openGunDrawer(id);return}if(action==='delete'){if(kind==='pile')removePile(id);else removeGun(id);return}if(action==='qr'){openQrModal(id);return}if(action==='exportQr'){exportQr(findPile(id));return}if(action==='replaceQr'){simpleModal('更换设备二维码','确认更换该充电桩的二维码？旧二维码将立即失效，但不影响正在进行的订单。',function(){var pile=findPile(id);pile.qrVersion++;recordCommand(pile,'重新生成二维码','{"version":'+pile.qrVersion+'}','执行成功','旧二维码已失效');toast('二维码已重新生成，旧码已失效')});return}runRemoteCommand(id,action)}
  function downloadBlob(filename,blob){var link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}
