  function openChargeOrderDrawer(id){var order=findTransactionOrder(id);if(!order)return;state.drawerKind='charge-order';state.editingDevice=id;el('drawerTitle').textContent='编辑订单备注';el('saveStation').textContent='保存订单备注';el('drawerBody').innerHTML='<div class="form-section">只读订单信息</div><div class="info-grid" style="margin-bottom:17px">'+infoItem('订单编号',escapeHtml(order.id))+infoItem('所属站点',escapeHtml(order.station))+infoItem('订单状态',pill(order.orderStatus||'已完成'))+infoItem('订单实收',financeMoney(order.amount)+' 元')+'</div><div class="form-item"><label class="filter-label" for="chargeOrderNote">订单备注</label><textarea class="finance-textarea" id="chargeOrderNote" maxlength="200" placeholder="补充异常说明、人工核查结论或客户反馈">'+escapeHtml(order.note||'')+'</textarea></div>';el('drawerOverlay').classList.remove('hidden')}
  function saveChargeOrderNote(){var id=state.editingDevice,order=findTransactionOrder(id);if(!order)return;order.note=el('chargeOrderNote').value.trim();order.noteUser='蒙奇奇';order.updated=new Date().toISOString().slice(0,16).replace('T',' ');closeDrawer();if(state.orderDetailId===id)showChargeOrderDetail(id,'操作记录');else renderTransactionModule(state.module);toast('订单备注已更新，计费与分账数据保持不变')}
  function applyOrderRefund(order){if(order.isFree||order.amount<=0){toast('免费订单无可退金额');return}if(financeInvoiceStatus(order.id)!=='未开票'){toast('订单已开票或开票中，暂不可发起退款');return}var remaining=financeNumber(order.amount-order.refundAmount);showModal('申请订单退款','<div class="info-grid" style="margin-bottom:13px">'+infoItem('订单编号',escapeHtml(order.id))+infoItem('支付方式',escapeHtml(orderSourceName(order)))+infoItem('可退金额',financeMoney(remaining)+' 元')+infoItem('分账状态',financeBadge(orderShareState(order)))+'</div>'+inputMarkup('orderRefundAmount','退款金额 (元)',financeFixed(remaining),true,'number')+'<div class="form-item"><label class="filter-label required">退款原因</label><textarea class="finance-textarea" id="orderRefundReason" placeholder="请输入退款原因和核查依据"></textarea></div>',[{label:'提交退款申请',primary:true,close:false,run:function(){var amount=Number(el('orderRefundAmount').value),reason=el('orderRefundReason').value.trim();if(!Number.isFinite(amount)||amount<=0||amount>remaining){toast('退款金额不能超过订单可退金额');return}if(!reason){toast('请填写退款原因');return}financeRefunds.unshift({id:'TK202608'+String(52001+financeRefunds.length),orderId:order.id,station:order.station,operator:order.operator,channel:order.channel,amount:financeNumber(amount),reason:reason,appliedAt:new Date().toISOString().slice(0,16).replace('T',' '),status:'待审核',reviewer:'',reviewedAt:'',rejectReason:'',audit:[]});closeModal();if(state.orderDetailId===order.id)showChargeOrderDetail(order.id,'支付与退款');else renderTransactionModule(state.module);toast('退款申请已提交，待财务审核')}}])}
  function runTransactionAction(name,id,action){if(name==='退款记录'){var refund=financeById(financeRefunds,id);if(!refund)return;if(action==='detail'){financeDetail('refund',refund);return}showChargeOrderDetail(refund.orderId);return}var record=name==='占位订单'?occupancyRows().find(function(row){return row.id===id}):findTransactionOrder(id);if(!record)return;var order=name==='占位订单'?findTransactionOrder(record.orderId):record;if(action==='detail'){showChargeOrderDetail(order.id,name==='占位订单'?'计费明细':'订单信息');return}if(action==='edit'){openChargeOrderDrawer(order.id);return}if(action==='refund'){applyOrderRefund(order);return}simpleModal('结束充电订单','确认结束正在充电的订单「'+escapeHtml(order.id)+'」？结束后系统将按实际分时电量重新计算费用。',function(){order.orderStatus='已完成';order.finished=new Date().toISOString().slice(0,16).replace('T',' ');order.stopReason='平台人工结束';order.paymentStatus='待支付';order.audit=(order.audit||[]).concat([{time:order.finished,user:'蒙奇奇',action:'平台人工结束充电'}]);renderTransactionModule('充电订单');toast('充电已结束，订单进入待支付流程')})}

  function businessMenu(kind,record){var actions=[{key:'detail',label:'查看详情'}];if(kind==='user')actions.push({key:record.status==='正常'?'disable':'enable',label:record.status==='正常'?'禁用用户':'启用用户',danger:record.status==='正常'});else if(kind==='operator')actions.push({key:'edit',label:'编辑运营商'});else if(kind==='free-user'){actions.push({key:'edit',label:'编辑免费资格'});if(['启用','未生效'].indexOf(record.status)!==-1)actions.push({key:'disable',label:'停用免费资格',danger:true});if(record.status==='停用')actions.push({key:'enable',label:'启用免费资格'});if(!record.historyCount)actions.push({key:'delete',label:'删除免费资格',danger:true})}else if(kind==='group'){actions.push({key:'edit',label:'编辑分组'},{key:record.status==='启用'?'disable':'enable',label:record.status==='启用'?'停用分组':'启用分组'},{key:'delete',label:'删除分组',danger:true})}else if(kind==='campaign'){actions.push({key:'edit',label:'编辑活动'});if(record.status==='进行中')actions.push({key:'pause',label:'暂停投放'});if(['已暂停','草稿'].indexOf(record.status)!==-1)actions.push({key:'publish',label:'发布活动'});if(['进行中','待开始','已暂停'].indexOf(record.status)!==-1)actions.push({key:'end',label:'结束活动',danger:true});if(['草稿','待开始','已结束'].indexOf(record.status)!==-1)actions.push({key:'delete',label:'删除活动',danger:true})}return '<div class="action-menu-wrap"><button class="more-button business-trigger" aria-label="记录操作">···</button><div class="row-menu">'+actions.map(function(action,index){return(index===1?'<div class="menu-divider"></div>':'')+'<button class="business-action '+(action.danger?'danger':'')+'" data-kind="'+kind+'" data-id="'+escapeHtml(record.id||record.name)+'" data-action="'+action.key+'">'+action.label+'</button>'}).join('')+'</div></div>'}
  function businessDate(record){return String(record.created||record.registered||record.start||'').slice(0,10)}
  function filteredBusinessRecords(options){return options.records.filter(function(record){var keyword=state.moduleKeyword.toLowerCase(),search=options.search(record).toLowerCase(),date=businessDate(record),type=options.type?options.type(record):'';return(!keyword||search.indexOf(keyword)!==-1)&&(!state.moduleOperator||(record.operator||record.name)===state.moduleOperator)&&(!state.moduleStatus||record.status===state.moduleStatus)&&(!state.moduleType||type===state.moduleType)&&(!state.moduleFrom||date>=state.moduleFrom)&&(!state.moduleTo||date<=state.moduleTo)})}
