  function groupRuleValue(user,field){return field==='近30天充电次数'?user.last30Charges:field==='注册天数'?user.registerDays:field==='最近充电间隔天数'?user.inactiveDays:field==='累计消费金额'?user.spent:field==='钱包余额'?user.balance:field==='用户状态'?user.status:user.region}
  function matchGroupRule(user,rule){var value=groupRuleValue(user,rule.field),expected=rule.value;if(rule.compare==='包含')return String(value).indexOf(expected)!==-1;if(rule.compare==='等于')return String(value)===String(expected)||Number(value)===Number(expected);if(rule.compare==='不等于')return String(value)!==String(expected);var actual=Number(value),target=Number(expected);if(rule.compare==='大于')return actual>target;if(rule.compare==='大于等于')return actual>=target;if(rule.compare==='小于')return actual<target;if(rule.compare==='小于等于')return actual<=target;return false}
  function groupMembers(group){return appUsers.filter(function(user){if(group.scope==='指定运营商用户'&&group.operator&&user.operator!==group.operator)return false;if(!group.rules.length)return true;return group.matchMode==='任一满足'?group.rules.some(function(rule){return matchGroupRule(user,rule)}):group.rules.every(function(rule){return matchGroupRule(user,rule)})})}
