  function captureGroupRules(){state.marketingRuleDraft.forEach(function(rule,index){if(!el('groupRuleField'+index))return;rule.field=el('groupRuleField'+index).value;rule.compare=el('groupRuleCompare'+index).value;rule.value=el('groupRuleValue'+index).value.trim()})}
